/* 1) 화면 코드 객체 — 전부 VALID */
SELECT OBJECT_NAME, OBJECT_TYPE, STATUS FROM USER_OBJECTS WHERE OBJECT_NAME IN ('PKG_SSP0046') ORDER BY 1, 2;

/* 2) 컴파일 오류 — 0건 */
