/* 3) GTT 구조 — 0건(사내와 다른 GTT 가 있으면 행) */
SELECT E.T AS TABLE_NAME
  FROM (SELECT 'GT_SSP0046_BOH' T, 'DIVISION_ID|VARCHAR2|30|||Y;ITEM_ID|VARCHAR2|50|||Y;FROM_SITE|VARCHAR2|30|||Y;YYYYMMDD|VARCHAR2|8|||Y;QTY|NUMBER|0|28|10|Y' S FROM DUAL
