    UNION ALL SELECT 'GT_SSP0046_LOC' T, 'SHT_NAME|VARCHAR2|10|||Y;DIVISION_ID|VARCHAR2|30|||Y;LOC_CODE|VARCHAR2|50|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SSP0046_MEASURE' T, 'MEASURE|VARCHAR2|200|||Y;MEASURE_LABEL|VARCHAR2|150|||Y;BIZ_TYPE|CHAR|1|||Y;SUM_CHECK|CHAR|1|||Y;MEASURE_COLOR|VARCHAR2|20|||Y;DEL_FLAG|CHAR|1|||Y;SEQ|NUMBER|0|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SSP0046_MKT' T, 'DIVISION_ID|VARCHAR2|30|||Y;PROJECT_CODE|VARCHAR2|50|||Y;SCM_SITE_ID|VARCHAR2|30|||Y;ITEM_ID|VARCHAR2|50|||Y;FCST_TYPE|VARCHAR2|10|||Y;INCOTERMS|VARCHAR2|10|||Y;BOD_ID|VARCHAR2|50|||Y;PLANT_SITE_ID|VARCHAR2|30|||Y;DM_YYYYMMDD|VARCHAR2|8|||Y;QTY|NUMBER|0|20|10|Y;END_CUSTOMER|VARCHAR2|50|||Y;DEPT|VARCHAR2|250|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SSP0046_PIVOT' T, 'DIVISION_ID|VARCHAR2|30|||Y;ITEM_ID|VARCHAR2|50|||Y;NICK_NAME|VARCHAR2|500|||Y;FROM_SITE|VARCHAR2|30|||Y;TO_SITE|VARCHAR2|30|||Y;DEPT|VARCHAR2|250|||Y;END_CUSTOMER|VARCHAR2|50|||Y;PROJECT_CODE|VARCHAR2|50|||Y;INCOTERMS|VARCHAR2|10|||Y;FCST_TYPE|VARCHAR2|10|||Y;TR_MODE|VARCHAR2|50|||Y;BOD_ID|VARCHAR2|50|||Y;MEASURE|VARCHAR2|50|||Y;YYYYMMDD|VARCHAR2|10|||Y;YYYYMM|VARCHAR2|6|||Y;ISO_WEEK|VARCHAR2|10|||Y;QTY|NUMBER|0|20|10|Y;SEQ|NUMBER|0|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SSP0046_PLAN' T, 'DIVISION_ID|VARCHAR2|30|||Y;ITEM_ID|VARCHAR2|50|||Y;FROM_SITE|VARCHAR2|30|||Y;TO_SITE|VARCHAR2|30|||Y;DEPT|VARCHAR2|250|||Y;END_CUSTOMER|VARCHAR2|50|||Y;PROJECT_CODE|VARCHAR2|50|||Y;INCOTERMS|VARCHAR2|10|||Y;FCST_TYPE|VARCHAR2|10|||Y;TR_MODE|VARCHAR2|50|||Y;BOD_ID|VARCHAR2|50|||Y;MEASURE|VARCHAR2|50|||Y;YYYYMMDD|VARCHAR2|8|||Y;QTY|NUMBER|0|20|10|Y;SEQ|NUMBER|0|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SSP0046_PLAN_FG' T, 'DIVISION_ID|VARCHAR2|30|||Y;PLAN_START_YYYYMMDD|VARCHAR2|8|||Y;PLAN_TYPE|VARCHAR2|10|||Y;SEQ|NUMBER|0|||Y;BIZ_TYPE|VARCHAR2|10|||Y;PROJECT_CODE|VARCHAR2|50|||Y;FCST_TYPE|VARCHAR2|10|||Y;ITEM_ID|VARCHAR2|50|||Y;TO_SITE|VARCHAR2|30|||Y;INCOTERMS|VARCHAR2|10|||Y;FROM_SITE|VARCHAR2|30|||Y;BOD_ID|VARCHAR2|50|||Y;TRANSPORT_MODE|VARCHAR2|50|||Y;MEASURE|VARCHAR2|50|||Y;YYYYMMDD|VARCHAR2|8|||Y;QTY|NUMBER|0|20|10|Y' S FROM DUAL
    UNION ALL SELECT 'GT_SSP0046_REQUESTOR' T, 'DIVISION_ID|VARCHAR2|30|||Y;ITEM_ID|VARCHAR2|50|||Y;FROM_SITE|VARCHAR2|30|||Y;TO_SITE|VARCHAR2|30|||Y;TR_MODE|VARCHAR2|50|||Y;INCOTERMS|VARCHAR2|10|||Y;FCST_TYPE|VARCHAR2|10|||Y;MEASURE|VARCHAR2|50|||Y;CREATED_BY|VARCHAR2|30|||Y' S FROM DUAL
