    UNION ALL SELECT 'GT_SSP0046_SHIP_REQ' T, 'DIVISION_ID|VARCHAR2|30|||Y;ITEM_ID|VARCHAR2|50|||Y;FROM_SITE|VARCHAR2|30|||Y;TO_SITE|VARCHAR2|30|||Y;DEPT|VARCHAR2|250|||Y;END_CUSTOMER|VARCHAR2|50|||Y;PROJECT_CODE|VARCHAR2|50|||Y;INCOTERMS|VARCHAR2|10|||Y;FCST_TYPE|VARCHAR2|10|||Y;TR_MODE|VARCHAR2|50|||Y;BOD_ID|VARCHAR2|50|||Y;MEASURE|VARCHAR2|50|||Y;YYYYMMDD|VARCHAR2|8|||Y;CREATED_BY|VARCHAR2|30|||Y;QTY|NUMBER|0|20|10|Y;SEQ|NUMBER|0|||Y;RN|NUMBER|0|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SSP0046_SHIP_ROW' T, 'DIVISION_ID|VARCHAR2|30|||Y;ITEM_ID|VARCHAR2|50|||Y;NICK_NAME|VARCHAR2|500|||Y;FROM_SITE|VARCHAR2|30|||Y;TO_SITE|VARCHAR2|30|||Y;DEPT|VARCHAR2|250|||Y;END_CUSTOMER|VARCHAR2|50|||Y;PROJECT_CODE|VARCHAR2|50|||Y;INCOTERMS|VARCHAR2|10|||Y;FCST_TYPE|VARCHAR2|10|||Y;TR_MODE|VARCHAR2|50|||Y;BOD_ID|VARCHAR2|50|||Y;MEASURE|VARCHAR2|50|||Y;YYYYMMDD|VARCHAR2|8|||Y;QTY|NUMBER|0|20|10|Y;SEQ|NUMBER|0|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SSP0046_STOCK' T, 'DIVISION_ID|VARCHAR2|30|||Y;SCM_SITE_ID|VARCHAR2|30|||Y;STORAGE_ID|VARCHAR2|30|||Y;ITEM_ID|VARCHAR2|150|||Y;SSP_QTY|NUMBER|0|28|10|Y;YYYYMMDD|VARCHAR2|8|||Y' S FROM DUAL) E
 WHERE NVL((SELECT LISTAGG(COLUMN_NAME||'|'||DATA_TYPE||'|'||CHAR_LENGTH||'|'||DATA_PRECISION||'|'||DATA_SCALE||'|'||NULLABLE, ';') WITHIN GROUP (ORDER BY COLUMN_ID)
              FROM USER_TAB_COLUMNS C WHERE C.TABLE_NAME = E.T), '~') <> E.S
 ORDER BY 1;

/* 4) META — 패키지 행이 클라우드에 모두 있음: MISSING = 0 */
SELECT 'SCM_ADM_MNU_M' AS TBL, '메뉴 행 (메뉴 트리·노출은 클라우드 운영값 존중 — 없을 때만)' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_MNU_M T WHERE NVL(TO_CHAR(T.MNU_ID), '~') = NVL(TO_CHAR(S.MNU_ID), '~')) THEN 0 ELSE 1 END) AS MISSING
  FROM (SELECT 'SSP0046' MNU_ID FROM DUAL) S;
SELECT 'SCM_ADM_API_M' AS TBL, '화면 전용 API' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_API_M T WHERE NVL(TO_CHAR(T.API_ID), '~') = NVL(TO_CHAR(S.API_ID), '~')) THEN 0 ELSE 1 END) AS MISSING
  FROM (SELECT 'SSP0046_CellBiz_SAVE' API_ID FROM DUAL
    UNION ALL SELECT 'SSP0046_CellBiz_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'SSP0046_PackBiz_SAVE' API_ID FROM DUAL
    UNION ALL SELECT 'SSP0046_PackBiz_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'SSP0046_spreadTitle_SEARCH' API_ID FROM DUAL
