    UNION ALL SELECT 'SSP0046' MNU_ID, 'Cell Biz' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SSP0046' MNU_ID, 'Pack Biz' SHT_NM, 'COLUMN_SETUP' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SSP0046' MNU_ID, 'Pack Biz' SHT_NM, 'DELETE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SSP0046' MNU_ID, 'Pack Biz' SHT_NM, 'EXCEL' MNU_BTN_CD FROM DUAL
