SELECT 'SCM_ADM_API_M' AS TBL, T.API_ID
  FROM SCM_MGR.SCM_ADM_API_M T
 WHERE (API_ID LIKE 'SSP0046' || '\_%' ESCAPE '\')
   AND NOT EXISTS (SELECT 1 FROM (SELECT 'SSP0046_CellBiz_SAVE' API_ID FROM DUAL
    UNION ALL SELECT 'SSP0046_CellBiz_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'SSP0046_PackBiz_SAVE' API_ID FROM DUAL
    UNION ALL SELECT 'SSP0046_PackBiz_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'SSP0046_spreadTitle_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'SSP0046_titleSet_SAVE' API_ID FROM DUAL
    UNION ALL SELECT 'SSP0046_titleSet_SEARCH' API_ID FROM DUAL) S WHERE NVL(TO_CHAR(T.API_ID), '~') = NVL(TO_CHAR(S.API_ID), '~'));
