  FROM SCM_MGR.SCM_ADM_MNU_BTN_MPG_M T
 WHERE (MNU_ID = 'SSP0046')
   AND NOT EXISTS (SELECT 1 FROM (SELECT 'SSP0046' MNU_ID, 'Cell Biz' SHT_NM, 'COLUMN_SETUP' MNU_BTN_CD FROM DUAL
